test("guard failure blocks the action with the exact error", async () => {
  clearWarnedModules();
  const previous = process.env.OPENCODE_GUARD_PYTHON;
  process.env.OPENCODE_GUARD_PYTHON = join(HERE, "missing-python");
  const errors = [];
  const originalError = console.error;
  console.error = (...args) => errors.push(args.join(" "));
  try {
    assert.throws(
      () => checkTool("read", { filePath: ".env" }, "/repo"),
      /block_paths unavailable/,
    );
    assert.equal(errors.length, 1);
    assert.match(errors[0], /block_paths unavailable/);

    const { hooks, ctx } = fakeContext("/repo");
    await plugin.setup(ctx);
    assert.throws(
      () =>
        hooks["tool:execute.before"]({
          tool: "shell",
          input: { command: "git status --short" },
        }),
      /BLOCKED: .*unavailable.*Refusing to run unguarded/,
    );

    const event = {
      action: "shell",
      resources: ["git status --short"],
      effect: "allow",
    };
    hooks["permission:evaluate"](event);
    assert.equal(event.effect, "deny");
    assert.match(event.message, /BLOCKED: .*unavailable/);
  } finally {
    console.error = originalError;
    if (previous === undefined) delete process.env.OPENCODE_GUARD_PYTHON;
    else process.env.OPENCODE_GUARD_PYTHON = previous;
  }
});

