test("registered hooks block commands, paths, patches, and permissions", async () => {
  const cwd = "/repo";
  const { hooks, ctx } = fakeContext(cwd);
  await plugin.setup(ctx);
  const before = hooks["tool:execute.before"];
  const evaluate = hooks["permission:evaluate"];

  assert.throws(
    () => before({ tool: "shell", input: { command: "git -C /repo push" } }),
    /BLOCKED: git push/,
  );
  assert.doesNotThrow(() =>
    before({ tool: "shell", input: { command: "git status --short" } }),
  );
  assert.throws(
    () => before({ tool: "shell", input: { command: "rm -rf build" } }),
    /BLOCKED: rm/,
  );
  // block_commands matches the `ssh` token inside the `.ssh` path first;
  // either guard blocking is acceptable, the path guard catches it too.
  assert.throws(
    () => before({ tool: "shell", input: { command: "cat ~/.ssh/id_rsa" } }),
    /BLOCKED: (ssh|access to ~\/.ssh)/,
  );
  assert.throws(
    () => before({ tool: "shell", input: { command: "git status && env" } }),
    /BLOCKED: environment dump/,
  );
  assert.throws(
    () =>
      before({
        tool: "shell",
        input: { command: "bash ~/.claude/skills/../../../usr/bin/env sh" },
      }),
    /BLOCKED: path traversal/,
  );
  // Relative shell paths must resolve against the session directory.
  assert.match(
    checkTool("shell", { command: "cat .aws/credentials" }, PY_HOME),
    /BLOCKED: access to ~\/.aws/,
  );

  const sshConfig = join(PY_HOME, ".ssh/config");
  assert.throws(
    () =>
      before({
        tool: "patch",
        input: { patchText: `*** Add File: ${sshConfig}\n+Host x\n` },
      }),
    /BLOCKED: access to ~\/.ssh/,
  );

  assert.doesNotThrow(() =>
    before({ tool: "read", input: { filePath: ".env.example" } }),
  );
  assert.throws(
    () => before({ tool: "read", input: { filePath: ".env" } }),
    /BLOCKED: access to \.env/,
  );
  // Non-shell permission actions reach the same path guard.
  assert.match(
    checkPermission("read", ["/repo/.env"], cwd),
    /BLOCKED: access to \.env/,
  );

  const event = { action: "shell", resources: ["git push origin main"], effect: "allow" };
  evaluate(event);
  assert.equal(event.effect, "deny");
  assert.match(event.message, /BLOCKED: git push/);
});
